<template><section class="cost-page"><header class="cost-page-heading"><div><h2>دسته‌بندی هزینه‌ها</h2><p>گروه‌هایی که برای ثبت و گزارش هزینه‌ها استفاده می‌شوند.</p></div><button class="cost-primary" @click="openCreate">دسته‌بندی جدید</button></header><form class="cost-filter" @submit.prevent="load"><input v-model.trim="search" placeholder="جستجوی دسته‌بندی"/><select v-model="status"><option value="">همه وضعیت‌ها</option><option value="true">فعال</option><option value="false">غیرفعال</option></select><button class="cost-primary">جستجو</button></form><div v-if="error" class="cost-notice" role="alert">{{error}} <button @click="load">تلاش مجدد</button></div><div class="category-list"><article v-for="category in filteredCategories" :key="category.id"><div><strong>{{category.name}}</strong><small>{{category.code||'بدون کد گزارش‌گیری'}}</small></div><div><span>تعداد هزینه‌ها</span><strong>{{number(category.expense_count)}} مورد</strong></div><div><span>مجموع هزینه</span><strong>{{money(category.total_spent)}}</strong></div><span :class="['status',category.is_active?'on':'off']">{{category.is_active?'فعال':'غیرفعال'}}</span><footer><button class="row-action" @click="openEdit(category)">ویرایش</button><button class="danger-action" @click="remove(category)">حذف</button></footer></article><div v-if="loading" class="empty-resource">در حال دریافت دسته‌بندی‌ها…</div><div v-else-if="!filteredCategories.length" class="empty-resource">دسته‌بندی‌ای پیدا نشد.</div></div><CategoryModal v-model="modalOpen" :category="editing" :loading="saving" :server-error="modalError" :field-errors="fieldErrors" @submit="save"/></section></template>
<script setup>import{computed,onMounted,ref}from'vue';import API from'@/api/transaction.api.js';import CategoryModal from'@/components/modals/CategoryModal.vue';import{costErrorMessage,formatCostNumber as number,formatMoney as money}from'@/utils/costControl';const categories=ref([]),search=ref(''),status=ref(''),loading=ref(false),saving=ref(false),error=ref(''),modalError=ref(''),fieldErrors=ref({}),modalOpen=ref(false),editing=ref(null),filteredCategories=computed(()=>categories.value.filter(item=>(!search.value||item.name.includes(search.value))&&(status.value===''||String(item.is_active)===status.value)));async function load(){loading.value=true;error.value='';try{categories.value=await API.getCategoryList()}catch(cause){error.value=costErrorMessage(cause)}finally{loading.value=false}}function openCreate(){editing.value=null;modalError.value='';fieldErrors.value={};modalOpen.value=true}function openEdit(category){editing.value=category;modalError.value='';fieldErrors.value={};modalOpen.value=true}async function save(payload){saving.value=true;modalError.value='';fieldErrors.value={};try{if(editing.value)await API.updateCategory(editing.value.id,payload);else await API.createCategory(payload);modalOpen.value=false;await load()}catch(cause){modalError.value=costErrorMessage(cause);fieldErrors.value=cause.cost?.errors||{}}finally{saving.value=false}}async function remove(category){if(!confirm(`دسته‌بندی «${category.name}» حذف شود؟`))return;try{await API.deleteCategory(category.id);await load()}catch(cause){error.value=costErrorMessage(cause)}}onMounted(load)</script>
<style scoped>.category-list{display:grid;gap:8px}.category-list article{display:grid;grid-template-columns:minmax(170px,1.4fr) repeat(2,minmax(130px,1fr)) auto auto;align-items:center;gap:14px;padding:13px 16px;background:var(--surface);border:1px solid var(--border);border-radius:11px}.category-list article>div{display:grid;gap:3px}.category-list span,.category-list small{color:var(--muted);font-size:.68rem}.category-list strong{font-size:.8rem}.category-list footer{display:flex}.category-list>.empty-resource{background:var(--surface);border:1px solid var(--border);border-radius:12px}@media(max-width:850px){.category-list article{grid-template-columns:repeat(2,minmax(0,1fr))}.category-list footer{justify-self:end}}@media(max-width:520px){.category-list article{grid-template-columns:1fr}.category-list footer{justify-self:start}}</style>
